parameters.jsCode:
// Get formatted blog content from SEO Formatter
  const formattedBlog = $('SEO Formatter').item.json.content[0].text;

  // Get metadata JSON from Metadata Generator
  const metadataResponse = $('Metadata Generator').item.json.content[0].text;

  // Extract JSON from metadata response
  let jsonMatch = metadataResponse.match(/\{[\s\S]*\}/);
  let metadata;

  if (jsonMatch) {
    metadata = JSON.parse(jsonMatch[0]);
  } else {
    metadata = {
      seoTitle: "Error: No valid JSON",
      seoDescription: "Error: No valid JSON",
      excerpt: "Error: No valid JSON",
      slug: "error-no-json",
      tags: []
    };
  }

  // Extract TLDR section from formatted blog
  let tldrMatch = formattedBlog.match(/## TLDR\n([\s\S]*?)(?=\n##)/);
  let tldr = tldrMatch ? tldrMatch[1].trim() : "Error: No TLDR found";

  // Remove TLDR section from full content
  let contentWithoutTLDR = formattedBlog.replace(/## TLDR\n[\s\S]*?(?=\n##)/, '').trim();

  // Get image URL from Generate an image node
  const imageUrl = $('Generate an image').item.json.url;

  // Return everything formatted for Airtable
  return {
    json: {
      seoTitle: metadata.seoTitle,
      seoDescription: metadata.seoDescription,
      excerpt: metadata.excerpt,
      slug: metadata.slug,
      tldr: tldr,
      tags: metadata.tags.join(', '),
      fullContent: contentWithoutTLDR,
      image: [{ url: imageUrl }]
    }
  };
